vals = [0.3, 0.7, 1.1]
def eq(f, g): return all(abs(float((f-g).subs(t, v))) < 1e-12 for v in vals)
assert eq(e, opts['A'])
for k in 'BCD':
    assert not eq(e, opts[k])

